import{_ as a,o as t,c as n,l as s,t as i,N as o}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"fifo | x-cmd man (man7) | first-in first-out special file, named pipe","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | fifo - first-in first-out special file, named pipe","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"fifo | x-cmd man (man7) | first-in first-out special file, named pipe"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | fifo - first-in first-out special file, named pipe"}]]},"headers":[],"params":{"isMan":true,"man":"fifo","category":"man7","desc":"first-in first-out special file, named pipe"},"relativePath":"man7/fifo.md","filePath":"man7/fifo.md"}'),r={name:"man7/fifo.md"},l={class:"visually-hidden"},p=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>fifo - first-in first-out special file, named pipe</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>A FIFO special file (a named pipe) is similar to a pipe, except that it is accessed as part of the filesystem. It can be opened by multiple processes for reading or writing. When processes are exchanging data via the FIFO, the kernel passes all data internally without writing it to the filesystem. Thus, the FIFO special file has no contents on the filesystem; the filesystem entry merely serves as a reference point so that processes can access the pipe using a name in the filesystem.</p><p>The kernel maintains exactly one pipe object for each FIFO special file that is opened by at least one process. The FIFO must be opened on both ends (reading and writing) before data can be passed. Normally, opening the FIFO blocks until the other end is opened also.</p><p>A process can open a FIFO in nonblocking mode. In this case, opening for read-only succeeds even if no one has opened on the write side yet and opening for write-only fails with <strong>ENXIO</strong> (no such device or address) unless the other end has already been opened.</p><p>Under Linux, opening a FIFO for read and write will succeed both in blocking and nonblocking mode. POSIX leaves this behavior undefined. This can be used to open a FIFO for writing while there are no readers available. A process that uses both ends of the connection in order to communicate with itself should be very careful to avoid deadlocks.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>For details of the semantics of I/O on FIFOs, see <strong>pipe</strong>(7).</p><p>When a process tries to write to a FIFO that is not opened for read on the other side, the process is sent a <strong>SIGPIPE</strong> signal.</p><p>FIFO special files can be created by <strong>mkfifo</strong>(3), and are indicated by <em>ls -l</em> with the file type &#39;p&#39;.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>mkfifo</strong>(1), <strong>open</strong>(2), <strong>pipe</strong>(2), <strong>sigaction</strong>(2), <strong>signal</strong>(2), <strong>socketpair</strong>(2), <strong>mkfifo</strong>(3), <strong>pipe</strong>(7)</p>',13);function c(e,d,f,h,m,g){return t(),n("div",null,[s("h1",l,i(e.$params.man),1),p])}const _=a(r,[["render",c]]);export{b as __pageData,_ as default};
